effect.shader:
const float BAYER4[16] = float[16](
     0.0/16.0,  8.0/16.0,  2.0/16.0, 10.0/16.0,
    12.0/16.0,  4.0/16.0, 14.0/16.0,  6.0/16.0,
     3.0/16.0, 11.0/16.0,  1.0/16.0,  9.0/16.0,
    15.0/16.0,  7.0/16.0, 13.0/16.0,  5.0/16.0
);

void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    vec2 p = floor(acScreenNorm * acResolution / scale);
    int ix = int(mod(p.x, 4.0));
    int iy = int(mod(p.y, 4.0));
    float t = BAYER4[iy * 4 + ix] - 0.5;
    float n = max(float(int(levels)) - 1.0, 1.0);
    vec3 q = floor(c.rgb * n + t * strength + 0.5) / n;
    fragColor = vec4(q, c.a);
}
